package com.neru.powlautotest

import android.graphics.Rect
import android.os.Handler
import android.os.Looper
import android.os.SystemClock
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/**
 * Passive test of a user-performed HOME touch. Accessibility does not expose
 * the raw MotionEvent delivered by the finger to another application.
 * No gestures are generated by this observer.
 */
internal class HomeManualComparison(
 private val service:PowlAccessibilityService,
 private val status:(String)->Unit
){
 companion object{
  private const val APP="jp.co.incrementp.milemobile"
  private const val FILENAME="home_manual_comparison.json"
  private const val WINDOW_MS=18_000L
  private fun file(ctx:android.content.Context)=File(ctx.filesDir,FILENAME)
  private fun data(ctx:android.content.Context):JSONObject=try{
   JSONObject(file(ctx).readText(Charsets.UTF_8))
  }catch(_:Exception){JSONObject().put("status","NOT_RECORDED")}
  fun export(ctx:android.content.Context):String=data(ctx).toString(2)
  fun summary(ctx:android.content.Context):String{
   val j=data(ctx)
   return if(j.optString("status")=="NOT_RECORDED")"指タップ比較：未実施"
   else "指タップ比較："+when(j.optString("outcome")){
    "AD_CONFIRMED"->"広告画面への遷移を確認"
    "NEXT_CONFIRMED"->"別の操作画面を確認"
    "HOME_REMAINED"->"HOMEのまま"
    "UNKNOWN"->"遷移先未確認"
    else->"まだ観測中"
   }+"／アプリCLICKイベント="+j.optBoolean("clickObserved")
  }
  fun compare(ctx:android.content.Context):String{
   val manual=data(ctx)
   val automated=try{JSONObject(HomeTrialJournal.export(ctx))}catch(_:Exception){JSONObject()}
   val attempts=automated.optJSONArray("attempts")?:JSONArray()
   val out=StringBuilder("HOME 指タップと自動操作の比較（Torima Auto v3.6）\n\n")
   out.append("【指で押した場合】\n").append(summary(ctx)).append("\n")
   out.append("観測開始からCLICKイベントまで: ")
   val click=manual.optLong("firstClickMs",-1)
   out.append(if(click>=0)"${click}ms" else "CLICKイベント未観測").append("\n")
   out.append("観測開始からHOME以外を確認: ")
   val changed=manual.optLong("firstChangedMs",-1)
   out.append(if(changed>=0)"${changed}ms" else "未確認").append("\n")
   out.append("観測開始から広告UI確認: ")
   val ad=manual.optLong("adConfirmedMs",-1)
   out.append(if(ad>=0)"${ad}ms" else "未確認").append("\n")
   out.append("【自動で押した場合】\n")
   for(i in 0 until attempts.length()){
    val a=attempts.optJSONObject(i)?:continue
    out.append("${i+1}. ${a.optString("method")} / ${a.optString("status")} / ")
    out.append("CLICK=${a.optBoolean("clickEventSeen")} / ")
    out.append("ジェスチャー完了=${a.optBoolean("gestureCompleted")}\n")
   }
   if(attempts.length()==0)out.append("同梱できる自動HOME試行はありません。\n")
   if(manual.optString("outcome") in listOf("AD_CONFIRMED","NEXT_CONFIRMED") &&
    (0 until attempts.length()).none{
     HomeOutcomePolicy.isConfirmed(attempts.optJSONObject(it)?.optString("status").orEmpty())
    } && attempts.length()>0){
    out.append("\n比較: 指ではHOMEから進めたが、自動では進めていない。\n")
    if(manual.optBoolean("clickObserved") && (0 until attempts.length()).any{
     attempts.optJSONObject(it)?.optBoolean("clickEventSeen")==true
    })out.append("双方でCLICK通知があっても結果が異なるため、CLICK通知は動画開始の保証ではありません。\n")
   }
   out.append("\n注意：他アプリに届く指の生MotionEvent、圧力、入力元の内部フラグや動画SDK内部の処理は取得できません。")
   out.append("画面状態、アクセシビリティイベント、時間差を比較する診断です。\n")
   return out.toString()
  }
 }
 private val handler=Handler(Looper.getMainLooper())
 private var active=false
 private var epoch=0
 private var begin=0L
 private var firstChanged=-1L
 private var firstAd=-1L
 private var latest="HOME"
 private var lastKey=""
 private var afterCaptureScheduled=false
 private var result=JSONObject()
 private var traces=JSONArray()
 private var clicks=JSONArray()
 fun isActive():Boolean=active
 private fun save(){try{file(service).writeText(result.toString(2),Charsets.UTF_8)}catch(_:Exception){}}
 private fun snapshot():JSONObject{
  val root=service.rootInActiveWindow
  val pkg=root?.packageName?.toString().orEmpty()
  val out=JSONObject().put("package",pkg)
  if(root==null)return out.put("state","NO_ROOT")
  val nodes=ArrayList<AccessibilityNodeInfo>()
  fun visit(n:AccessibilityNodeInfo){
   if(nodes.size>=300)return
   nodes.add(n)
   for(i in 0 until n.childCount){
    if(nodes.size>=300)break
    n.getChild(i)?.let{visit(it)}
   }
  }
  visit(root)
  val visible=nodes.filter{it.isVisibleToUser}
  val words=visible.flatMap{listOf(it.text?.toString().orEmpty(),
   it.contentDescription?.toString().orEmpty())}
  val remaining=words.firstOrNull{
   Regex("""あと\s*[0-9０-９]+\s*回獲得できます""").containsMatchIn(it)
  }.orEmpty()
  val move=visible.any{it.isSelected && it.contentDescription?.toString()=="move"}
  val separator=words.any{it.trim()=="または"}
  val tank=words.any{it.contains("タンクが満タン")}
  val home=pkg==APP && remaining.isNotBlank() && move && (separator||tank)
  val ad=words.any{
   it.contains("Ads served by Meta",true)||
   it.contains("Sponsored",true)||
   it.contains("Close Ad",true)||
   Regex("""Ad\s+[0-9]+\s+of\s+[0-9]+""",RegexOption.IGNORE_CASE).containsMatchIn(it)
  }
  val next=words.any{
   it.contains("ガチャWチャンスに挑戦")||
   it.contains("動画を見て再チャレンジ")||
   it.contains("カードを1枚選んでください")||
   it.contains("動画スキップ")
  }
  val state=when{
   home->"HOME"
   pkg!="jp.co.incrementp.milemobile"->"OTHER_APP"
   ad->"AD"
   next->"NEXT"
   visible.size<5->"OPAQUE"
   else->"OTHER"
  }
  out.put("state",state).put("nodes",nodes.size)
   .put("visibleNodes",visible.size).put("remaining",remaining)
   .put("moveSelected",move).put("separator",separator)
   .put("tank",tank).put("adEvidence",ad)
  val buttons=JSONArray()
  for(n in visible.filter{it.isClickable&&it.isEnabled}.take(45)){
   val r=Rect();n.getBoundsInScreen(r)
   if(r.width()<300||r.height()<70)continue
   buttons.put(JSONObject().put("bounds",r.toShortString())
    .put("class",n.className?.toString().orEmpty())
    .put("viewId",n.viewIdResourceName.orEmpty())
    .put("enabled",n.isEnabled).put("selected",n.isSelected))
   if(buttons.length()>=5)break
  }
  out.put("largeClickableNodes",buttons)
  return out
 }
 private fun record(stage:String,snapshot:JSONObject){
  if(traces.length()>=70)return
  traces.put(JSONObject().put("stage",stage)
   .put("elapsedMs",if(begin==0L)-1L else SystemClock.elapsedRealtime()-begin)
   .put("wallTime",System.currentTimeMillis()).put("snapshot",snapshot))
  result.put("states",traces)
  save()
 }
 fun start():String{
  if(active)return "指タップ比較は実行中です"
  val before=snapshot()
  if(before.optString("state")!="HOME")
   return "指タップ比較はトリマのHOME紫ボタン画面で開始してね（現在：${before.optString("state")}）"
  active=true;epoch++
  val token=epoch
  begin=0L;firstChanged=-1L;firstAd=-1L;latest="HOME"
  lastKey="";afterCaptureScheduled=false
  traces=JSONArray();clicks=JSONArray()
  result=JSONObject().put("version","3.6").put("status","ARMING")
   .put("outcome","RECORDING").put("startedAt",System.currentTimeMillis())
   .put("initialScreen",before).put("clickObserved",false)
   .put("rawFingerEventsUnavailable",true)
  save()
  status("指タップ比較を準備中。数秒後、紫ボタンを指で1回だけ押してね")
  service.prepareManualHomeObservation{ready,info->
   if(!active||epoch!=token)return@prepareManualHomeObservation
   if(!ready){
    result.put("error",info)
    finish("UNKNOWN")
    return@prepareManualHomeObservation
   }
   begin=SystemClock.elapsedRealtime()
   result.put("status","RECORDING").put("overlayInfo",info)
   record("baseline",snapshot())
   service.saveVisualScreenshot("手動指タップ・直前",0,false)
   status("指タップ比較18秒間：HOME紫ボタンを指で1回押して、ほかは触らず待ってね")
   poll(token)
  }
  return "指タップ比較を開始。紫ボタンを指で1回押して、18秒待ってね"
 }
 fun onEvent(event:AccessibilityEvent){
  if(!active||begin==0L||event.packageName?.toString()!=APP)return
  if(event.eventType!=AccessibilityEvent.TYPE_VIEW_CLICKED)return
  if(clicks.length()>=30)return
  val delta=SystemClock.elapsedRealtime()-begin
  val source=event.source
  val r=Rect();source?.getBoundsInScreen(r)
  clicks.put(JSONObject().put("elapsedMs",delta)
   .put("eventTime",event.eventTime).put("sourceBounds",r.toShortString())
   .put("sourceClass",source?.className?.toString().orEmpty())
   .put("sourceId",source?.viewIdResourceName.orEmpty())
   .put("sourceDesc",source?.contentDescription?.toString().orEmpty().take(80)))
  result.put("clickEvents",clicks).put("clickObserved",true)
  if(!result.has("firstClickMs")){
   result.put("firstClickMs",delta)
   if(!afterCaptureScheduled){
    afterCaptureScheduled=true
    val id=epoch
    handler.postDelayed({
     if(id==epoch)service.saveVisualScreenshot("手動指タップ・クリック後",0,false)
    },2_600L)
   }
  }
  save()
 }
 private fun poll(token:Int){
  if(!active||token!=epoch)return
  val elapsed=SystemClock.elapsedRealtime()-begin
  val s=snapshot()
  val state=s.optString("state")
  if(state!="HOME"&&firstChanged<0){
   firstChanged=elapsed
   result.put("firstChangedMs",elapsed)
   record("first_non_home",s)
   if(!afterCaptureScheduled){
    afterCaptureScheduled=true
    val id=epoch
    handler.postDelayed({
     if(id==epoch)service.saveVisualScreenshot("手動指タップ・画面変化後",0,false)
    },2_600L)
   }
  }
  if(state=="AD"&&firstAd<0){
   firstAd=elapsed
   result.put("adConfirmedMs",elapsed)
   record("ad_evidence",s)
  }
  val key="${state}:${s.optInt("nodes")}:${s.optString("remaining")}"
  if(key!=lastKey){
   record("state_changed",s)
   lastKey=key
  }
  latest=state
  if(elapsed>=18_000L){
   finish(when{
    firstAd>=0->"AD_CONFIRMED"
    state=="NEXT"->"NEXT_CONFIRMED"
    state=="HOME"->"HOME_REMAINED"
    else->"UNKNOWN"
   })
  }else handler.postDelayed({poll(token)},400L)
 }
 fun finish(outcome:String="UNKNOWN"){
  if(!active)return
  active=false;epoch++
  result.put("status","FINISHED").put("outcome",outcome)
   .put("endedAt",System.currentTimeMillis()).put("finalState",latest)
   .put("finalScreen",snapshot())
  save()
  service.restoreHomeTouch()
  status("指タップ比較終了：${summary(service)}。あとはアプリの一括ZIPを送ってね")
 }
 fun cancel(){if(active)finish("UNKNOWN")}
}
